        <span class="badge badge-sm badge-ghost">{{ selectedAttachments.length }}</span>
      </div>
      <button 
        v-if="selectedAttachments.length > 0"
        class="btn btn-xs btn-ghost"
        @click="clearAll"
        title="Clear all attachments"
      >
        <i class="fa-solid fa-trash text-error"></i>
      </button>
    </div>

    <!-- Empty state -->
    <div v-if="fileObjects.length === 0" class="text-center py-6 text-base-content/50">
      <i class="fa-solid fa-inbox text-2xl block mb-2"></i>
      <p class="text-sm">No attachments to display</p>
    </div>

    <!-- Attachment Grid -->
    <div v-else class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2 max-h-96 overflow-y-auto">
      <div
        v-for="(attachment, idx) in fileObjects"
        :key="idx"
        class="relative group rounded-lg border transition-all"
        :class="isSelected(idx) 
          ? 'bg-primary/10 border-primary shadow-md' 
          : 'bg-base-100 border-base-300 hover:border-base-400'"
      >
        <!-- Image Preview or Icon -->
        <div class="relative w-full aspect-square overflow-hidden rounded-t-lg bg-base-300/30 flex items-center justify-center">
          <!-- Image Attachment -->
          <img
            v-if="attachment.isImage()"
            :src="`data:${attachment.file_type};base64,${attachment.base64_data}`"
            :alt="attachment.file_name"
            class="w-full h-full object-cover"
          />
          <!-- Document/Other File -->
          <div v-else class="flex flex-col items-center gap-2 text-base-content/60">
            <i :class="getFileIcon(attachment)" class="text-3xl"></i>
            <span class="text-xs text-center px-2 truncate max-w-full">
              {{ attachment.getExtension().toUpperCase() }}
            </span>
          </div>

          <!-- Selection Checkbox Overlay -->
          <div class="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-all rounded-t-lg flex items-center justify-center">
            <input
              type="checkbox"
              :checked="isSelected(idx)"
              @change="toggleSelection(idx)"
              class="w-6 h-6 rounded cursor-pointer checkbox checkbox-primary"
            />
          </div>
        </div>

        <!-- File Info -->
        <div class="p-2 bg-base-100 rounded-b-lg">
          <!-- File Name -->
          <div class="text-xs font-medium truncate" :title="attachment.file_name">
            {{ attachment.file_name }}
          </div>

          <!-- File Meta -->
          <div class="text-xs text-base-content/60 flex justify-between mt-1">
            <span>{{ attachment.getFormattedSize() }}</span>
            <span class="text-right">{{ formatDate(attachment.uploaded_at) }}</span>
          </div>

          <!-- Action Buttons -->
          <div class="flex gap-1 mt-2">
            <button
              class="btn btn-xs btn-ghost flex-1"
              @click="downloadAttachment(attachment)"
              title="Download file"
            >
              <i class="fa-solid fa-download"></i>
              <span class="text-xs">Download</span>
            </button>
            <button
              class="btn btn-xs"
              :class="isSelected(idx) ? 'btn-error' : 'btn-primary'"
              @click="toggleSelection(idx)"
