            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- Summary -->
    <div v-if="fileObjects.length > 0" class="flex items-center justify-between text-xs text-base-content/60 border-t border-base-300 pt-2">
      <span>
        Selected: <span class="font-semibold text-base-content">{{ selectedAttachments.length }} / {{ fileObjects.length }}</span>
      </span>
      <span>
        Total size: <span class="font-semibold text-base-content">{{ getTotalSize() }}</span>
      </span>
    </div>
  </div>
</template>

<script>
import ChatAttachment from '@/api/model/ChatAttachment.js'

export default {
  name: 'ChatAttachmentPreview',
  props: {
    attachments: {
      type: Array,
      default: () => [],
      validator(value) {
        return Array.isArray(value)
      }
    }
  },
  emits: ['selected-attachments-change'],
  data() {
    return {
      selectedIndices: new Set(),
      fileObjects: []
    }
  },
  watch: {
    attachments: {
      immediate: true,
      handler(newVal) {
        this.fileObjects = newVal.map(attachment => {
          if (attachment instanceof ChatAttachment) {
            return attachment
          }
          return ChatAttachment.fromJSON(attachment)
        })
      }
    },
    selectedIndices: {
      handler() {
        this.emitSelectedAttachments()
      }
    }
  },
  computed: {
    selectedAttachments() {
      return Array.from(this.selectedIndices)
        .map(idx => this.fileObjects[idx])
        .filter(Boolean)
    }
  },
  methods: {
    toggleSelection(idx) {
      if (this.selectedIndices.has(idx)) {
        this.selectedIndices.delete(idx)
      } else {
        this.selectedIndices.add(idx)
      }
      this.selectedIndices = new Set(this.selectedIndices)
    },

    isSelected(idx) {
      return this.selectedIndices.has(idx)
    },

    clearAll() {
      this.selectedIndices.clear()
      this.selectedIndices = new Set(this.selectedIndices)
    },

    selectAll() {
      this.fileObjects.forEach((_, idx) => {
        this.selectedIndices.add(idx)
      })
      this.selectedIndices = new Set(this.selectedIndices)
    },

    getFileIcon(attachment) {
      const ext = attachment.getExtension()
      const iconMap = {
        'pdf': 'fa-file-pdf text-red-500',
        'doc': 'fa-file-word text-blue-500',
        'docx': 'fa-file-word text-blue-500',
        'xls': 'fa-file-excel text-green-500',
        'xlsx': 'fa-file-excel text-green-500',
        'ppt': 'fa-file-powerpoint text-orange-500',
        'pptx': 'fa-file-powerpoint text-orange-500',
        'txt': 'fa-file-lines text-gray-500',
        'zip': 'fa-file-zipper text-yellow-600',
        'json': 'fa-file-code text-purple-500',
        'xml': 'fa-file-code text-purple-500'
      }
      return 'fa-solid ' + (iconMap[ext] || 'fa-file text-base-content/40')
    },

    downloadAttachment(attachment) {
      const link = document.createElement('a')
      const dataUrl = `data:${attachment.file_type};base64,${attachment.base64_data}`
      link.href = dataUrl
      link.download = attachment.file_name
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    },

    formatDate(dateString) {
      try {
        const date = new Date(dateString)
        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
      } catch {
        return 'Unknown'
      }
    },

    getTotalSize() {
      const total = this.fileObjects.reduce((sum, att) => sum + att.file_size, 0)
      return ChatAttachment.formatSize?.(total) || this.formatBytes(total)
    },

    formatBytes(bytes) {
      const units = ['B', 'KB', 'MB', 'GB']
      let size = bytes
      let unitIndex = 0
      while (size >= 1024 && unitIndex < units.length - 1) {
        size /= 1024
        unitIndex++
      }
      return `${size.toFixed(2)} ${units[unitIndex]}`
    },

    emitSelectedAttachments() {
      this.$emit('selected-attachments-change', this.selectedAttachments)
    }
  }
}
</script>

<style scoped>
.checkbox:checked {
  @apply bg-primary border-primary;
}

/* Smooth transitions for hover effects */
.group:hover {
  @apply shadow-sm;
}
</style>
```

