      const total = this.fileObjects.reduce((sum, att) => sum + att.file_size, 0)
      return ChatAttachment.formatSize?.(total) || this.formatBytes(total)
    },

    formatBytes(bytes) {
      const units = ['B', 'KB', 'MB', 'GB']
      let size = bytes
      let unitIndex = 0
      while (size >= 1024 && unitIndex < units.length - 1) {
        size /= 1024
        unitIndex++
      }
      return `${size.toFixed(2)} ${units[unitIndex]}`
    },

    emitSelectedAttachments() {
      this.$emit('selected-attachments-change', this.selectedAttachments)
    }
  }
}
