      </div>

      <!-- Main Chat View -->
      <div class="grow flex gap-2 min-h-0 overflow-hidden" v-show="!isPRView">

        <!-- Message Editor Mode -->
        <div class="w-full h-full" v-if="editMessage">
          <ChatMessageEditor
